BEGIN;

CREATE TABLE IF NOT EXISTS policy_settings (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  policy_version VARCHAR(30) NOT NULL UNIQUE,
  response_hours INTEGER NOT NULL DEFAULT 48 CHECK (response_hours > 0),
  appeal_hours INTEGER NOT NULL DEFAULT 72 CHECK (appeal_hours > 0),
  return_damage_report_hours INTEGER NOT NULL DEFAULT 24 CHECK (return_damage_report_hours > 0),
  evidence_retention_days INTEGER NOT NULL DEFAULT 10 CHECK (evidence_retention_days > 0),
  grace_period_minutes INTEGER NOT NULL DEFAULT 0 CHECK (grace_period_minutes >= 0),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

UPDATE policy_versions
SET body = $policy$
مسودة سياسة المنصة للحجوزات والتسليم والاستلام وإدارة الشكاوى والنزاعات
الإصدار المعتمد: 1.1 — اللغة المعتمدة عند التعارض: العربية

1. نطاق السياسة وقوتها
تطبق هذه السياسة على كل حجز أو طلب تأجير يتم إنشاؤه من خلال المنصة، وعلى العميل والمورد والموظفين المفوضين والإدارة. يعد إنشاء الحجز أو قبوله أو دفع قيمته أو استلام السيارة قبولاً للأحكام التشغيلية، مع عرض السياسة قبل الإجراء وتسجيل النسخة المقبولة. تعد سجلات الحجز، ومنها الدفع والرسائل والصور وتقارير التسليم والاستلام والعداد والوقود والموقع والتعديلات الإدارية، جزءاً من ملف النزاع. لا يعتد بأي اتفاق شفهي غير موثق داخل المنصة، ويجب تسجيل أي اتفاق خاص في محادثة الحجز أو حقل رسمي قابل للمراجعة.

2. الأدوار والالتزامات
يلتزم العميل بتقديم بيانات صحيحة ودفع المستحقات وفحص السيارة والمحافظة عليها وإعادتها في الموعد والمكان المحددين. يلتزم المورد بامتلاك حق التأجير وتقديم سيارة مطابقة وآمنة وتوثيق التسليم والاستلام وتحديث حالة السيارة والحجز. ينفذ الموظف المفوض صلاحياته المحددة فقط ولا يصدر قراراً مالياً أو قرار نزاع خارج التفويض المسجل. تراجع الإدارة الأدلة وتصدر قراراً مسبباً وتسجل أثره على الحجز والمبالغ.

3. تكوين الحجز وإلزاميته
لا يصبح الحجز نهائياً إلا بعد ظهور حالة الحجز النهائية واستيفاء متطلبات الدفع أو الموافقة. يجب أن يتضمن ملف الحجز السيارة والمورد والعميل ومواعيد ومكان الاستلام والإعادة والسعر والخدمات الإضافية والملاحظات. لا يجوز للمورد تغيير السيارة أو السعر أو الشروط الجوهرية بعد التأكيد دون موافقة العميل وتوثيق التعديل. عند تعذر توفير السيارة يجب إخطار المنصة والعميل فوراً، ويجوز للإدارة الإلغاء ومعالجة المبلغ حسب السبب والأدلة.

4. الاستلام ومحضر التسليم
قبل التسليم يتحقق الطرفان من الهوية والحجز ورخصة القيادة والوثائق وملاءمة السيارة. يجب إنشاء محضر تسليم قبل انتقال الحيازة ويتضمن، بحسب المتاح، صور الجهات الخارجية الأربع والمقدمة والمؤخرة والمقصورة والعداد والوقود أو البطارية والإطارات والملحقات، وقراءة العداد، ووصف الخدوش والكسور والعيوب السابقة، والوقت والمكان، وملاحظات الطرفين ونتيجة المطابقة. عند تسجيل اختلاف يجب وصفه وإرفاق صورة واحدة على الأقل أو وصف مفصل عند تعذر التصوير. لا يسقط التأكيد المطابق حق العيب المخفي، لكنه يعد قرينة قوية على الحالة الظاهرة. يضعف غياب تقرير المورد قدرته على إثبات الضرر السابق، ويضعف رفض العميل الفحص اعتراضه على العيوب الظاهرة.

5. استخدام السيارة والحوادث
يحظر التأجير من الباطن أو تمكين سائق غير مصرح له أو السباق أو السحب أو التحميل غير المناسب أو النشاط المحظور أو العبث بالعداد أو أجهزة التتبع أو أنظمة السلامة أو الخروج من النطاق المسموح أو الإصلاح دون موافقة، إلا للطوارئ. يجب إبلاغ المورد والمنصة فوراً عند حادث أو عطل أو فقدان أو ضبط أو تلف، والاحتفاظ بالصور والمستندات والشهود والبلاغات.

6. الإعادة وإغلاق الحجز
تعاد السيارة في الموعد والمكان المحددين، وينشئ الطرفان محضر استلام نهائياً يتضمن صوراً مماثلة، والعداد والوقود والملحقات والحالة والوقت والمكان. يحسب التأخير بعد فترة السماح المعتمدة، ولا يفرض رسم غير معلن أو غير مثبت. فترة السماح الافتراضية المعتمدة في النظام حالياً: صفر دقيقة. عند عدم حضور أحد الطرفين يوثق وقت الانتظار والموقع ومحاولات الاتصال.

7. الأضرار والمسؤولية
لا يتحمل العميل الضرر المثبت في تقرير التسليم، والاستهلاك الطبيعي، والعطل غير المرتبط بسوء الاستخدام، والعيب المخفي المثبت سابقاً أو غير القابل للاكتشاف بالفحص المعتاد. ويتحمل مبدئياً الضرر الذي ظهر بعد التسليم ولم يوثق قبله أو نتج عن مخالفة أو إهمال أو حادث أو سوء قيادة أو فقدان ملحق أو إعادة مختلفة جوهرياً. لا تفرض قيمة الضرر على تقدير شفهي فقط، بل تدعم بصور قبل وبعد ووصف وتقدير إصلاح أو فاتورة أو تقرير فني متى أمكن.

8. الشكاوى والنزاعات
يجوز فتح نزاع حول عدم التسليم أو المطابقة أو الضرر أو النظافة أو الوقود أو العداد أو التأخير أو مبلغ غير متفق عليه أو الإلغاء أو الاسترداد أو السلوك المخالف. يجب الإبلاغ عن اختلاف التسليم قبل تحريك السيارة متى أمكن، وعن ضرر الإعادة فور اكتشافه وبحد أقصى خلال 24 ساعة من وقت الإعادة، ما لم يوجد مانع موثق. يجب أن تتضمن الشكوى رقم الحجز ونوع المشكلة والوصف الزمني والمبلغ والأدلة والإجراء المطلوب. الشكوى العامة أو المهينة أو الخالية من الوقائع لا تكفي لإثبات المسؤولية.

9. إدارة النزاع
عند فتح النزاع تسجل المنصة النزاع في ملف الحجز وتغير حالته إلى متنازع عليه، ويجوز تعليق الإغلاق والتسوية المالية المتعلقة بالنقطة المتنازع عليها. يمنح الطرف الآخر مهلة 48 ساعة للرد وتقديم الأدلة. تراجع الإدارة تقارير التسليم والاستلام المؤرخة، ثم الصور والفيديو المرتبطين بالوقت والحجز، ثم العداد والوقود والموقع، ثم الرسائل وسجل الاتصال، ثم الفواتير والتقارير، ثم أقوال الأطراف والشهود والقرائن التقنية. تصدر الإدارة قبولاً كلياً أو جزئياً أو رفضاً أو طلب معلومات إضافية أو إغلاقاً إدارياً. يجب أن يتضمن القرار السبب والأدلة والمسؤول عن الإجراء والأثر المالي وموعد التنفيذ. يجوز اعتراض واحد خلال 72 ساعة من الإبلاغ بشرط دليل جديد أو خطأ محدد، ويراجعه شخص مختلف متى أمكن.

10. الضمانات والتعويضات
لا يخصم مبلغ إلا إذا كان مرتبطاً بالحجز ومنصوصاً عليه أو قابلاً للإثبات ومتناسباً وموثقاً بفاتورة أو تقدير أو قرار إداري مسبب. يعتمد الأقل من تكلفة الإصلاح المعقولة أو الضرر المثبت مع مراعاة الاستهلاك الطبيعي. يجوز تعليق الجزء المتنازع عليه مؤقتاً حتى وصول التقرير أو الفاتورة، ولا يعد ذلك غرامة تلقائية. لا تتحمل المنصة التعويض لمجرد الخلاف إلا عند ثبوت تقصير مستقل منها.

11. الإلغاء والاسترداد
عند إلغاء العميل قبل الاستلام: استرداد 100% إذا بقيت 72 ساعة أو أكثر، و75% إذا بقيت من 24 إلى أقل من 72 ساعة، و50% إذا بقي أقل من 24 ساعة، ولا يوجد إلغاء عادي بعد موعد الاستلام. يعالج إلغاء المورد بالاسترداد الكامل وفق مسار النظام، مع حق الإدارة في مراجعة الاحتيال أو إساءة الاستخدام.

12. المخالفات
يجوز اتخاذ إجراء متدرج: تنبيه موثق، طلب تصحيح أو مستندات، إيقاف سيارة أو إعلان، تعليق حجز أو دفع أو نشر، خصم مبلغ مثبت عند وجود التزام واضح، تعليق الحساب، أو إغلاقه ومنع إعادة التسجيل عند الاحتيال الجسيم. لا تفرض عقوبة دون سبب وواقعة ودليل وقرار صاحب الصلاحية.

13. القوة القاهرة
تراجع الإدارة القوة القاهرة والكوارث وإغلاق الطرق والقرارات الرسمية وأعطال مزود الدفع أو الاستضافة والوقائع الخارجة عن السيطرة بناء على الإثباتات، وتحدد أثرها على الحجز دون ضمان نتيجة مسبقة.

14. الاحتفاظ بالأدلة والحذف
تحتفظ المنصة بتقارير وصور التسليم والاستلام لمدة 10 أيام بعد إغلاق الحجز إذا لم توجد شكوى أو نزاع. إذا وجدت شكوى أو نزاع، يبدأ احتساب 10 أيام من تاريخ حل الشكوى أو إغلاق النزاع. لا تحذف المنصة أي تقرير أو صورة أو دليل مرتبط بملف مفتوح أو مطالبة مالية أو اعتراض أو إجراء قانوني. يسجل الحذف الآلي في سجل التدقيق، ولا يحذف سجل الحجز أو قرار الإدارة.

15. الإقرار
يقر العميل والمورد بقراءة هذه السياسة وفهم أثر الصور والعداد والوقود والتقارير على المطالبات، وبالالتزام بمهل الإبلاغ والرد والاعتراض والقرار الداخلي المسبب.
$policy$,
    version = '1.1', status = 'effective', effective_at = NOW()
WHERE version = '1.0';

INSERT INTO policy_settings (policy_version, response_hours, appeal_hours, return_damage_report_hours, evidence_retention_days, grace_period_minutes)
VALUES ('1.1', 48, 72, 24, 10, 0)
ON CONFLICT (policy_version) DO UPDATE SET response_hours=EXCLUDED.response_hours, appeal_hours=EXCLUDED.appeal_hours, return_damage_report_hours=EXCLUDED.return_damage_report_hours, evidence_retention_days=EXCLUDED.evidence_retention_days, grace_period_minutes=EXCLUDED.grace_period_minutes, updated_at=NOW();

COMMIT;
